#include <unordered_map>
#include <unordered_set>
#include <list>
#include <string>

using namespace std;

class AllOne {
    struct Bucket {
        int count;
        unordered_set<string> keys;
    };

    list<Bucket> buckets;
    unordered_map<string, list<Bucket>::iterator> keyToBucket;

public:
    AllOne() {}

    void inc(string key) {
        if (keyToBucket.count(key)) {
            auto it = keyToBucket[key];
            auto next = it;
            ++next;

            if (next == buckets.end() || next->count > it->count + 1) {
                next = buckets.insert(next, {it->count + 1, {}});
            }
            next->keys.insert(key);
            keyToBucket[key] = next;

            it->keys.erase(key);
            if (it->keys.empty()) buckets.erase(it);
        } else {
            if (buckets.empty() || buckets.front().count > 1) {
                buckets.push_front({1, {key}});
            } else {
                buckets.front().keys.insert(key);
            }
            keyToBucket[key] = buckets.begin();
        }
    }

    void dec(string key) {
        auto it = keyToBucket[key];
        if (it->count == 1) {
            keyToBucket.erase(key);
            it->keys.erase(key);
            if (it->keys.empty()) buckets.erase(it);
        } else {
            auto prev = it;
            --prev;
            if (it == buckets.begin() || prev->count < it->count - 1) {
                prev = buckets.insert(it, {it->count - 1, {}});
            }
            prev->keys.insert(key);
            keyToBucket[key] = prev;

            it->keys.erase(key);
            if (it->keys.empty()) buckets.erase(it);
        }
    }

    string getMaxKey() {
        return buckets.empty() ? "" : *buckets.back().keys.begin();
    }

    string getMinKey() {
        return buckets.empty() ? "" : *buckets.front().keys.begin();
    }
};
